#!/usr/bin/env python3
"""Generate Checks4D.lean: kernel-checked equality of the Challenge4D generator matrices
`D4Gen q k c` with the independent audit rebuild (`dim4audit_build.py` (research repository)).

usage (from the repository root):
  mkdir -p /tmp/d4gens
  python3 ../dim4audit_build.py hill_q11 2 3 --nobox --write 5,7,9 --out /tmp/d4gens
  python3 scripts/gen_checks4d.py /tmp/d4gens Checks4D.lean
"""
import os,sys
G=sys.argv[1]; out=sys.argv[2]
lines=["module","public import ChallengeDim34","","@[expose] public section","",
"/-! Generated by `scripts/gen_checks4d.py` -- do not edit by hand.",
"Fidelity check (NOT part of the default build): the Challenge generator matrices `D4Gen q k c`",
"(graph form, index = cell vector) equal, entry by entry, the matrices written by the independent",
"audit rebuild `dim4audit_build.py` (research repository) hill_q11 2 3 --write 5,7,9` (Definition N built",
"literally: raw frame graph form `O G⁻¹` over `ℚ`, gauge `λ_c = λ'_c Q_c^(-k)`,",
"`U_d = Q_d^k Toep(g_d) U'^(k)_d` with `α_n, β_n` solved by linear algebra, reduced mod `q`). -/","",
"namespace Z3NetD4.Checks","","open Z3NetD4 Matrix",""]
for q in (5,7,9):
    for k in (2,3):
        fn=os.path.join(G,f"hill_q11_q{q}_k{k}.gen")
        rows=[list(map(int,l.split())) for l in open(fn).read().strip().split('\n')[1:]]
        m=4*k
        for c in range(4):
            M=rows[c*m:(c+1)*m]
            lit="!![" + "; ".join(", ".join(str(x) for x in r) for r in M) + "]"
            lines.append(f"example : D4Gen {q} {k} {c} = {lit} := by")
            lines.append("  decide +kernel")
lines += ["","end Z3NetD4.Checks",""]
open(out,'w').write("\n".join(lines))
